// Inside the kiln, cut open along its length: a steel shell lined with fire brick, sloping down to the flame. The raw
// meal slides in at the high end, tumbles as the tube turns, and near the flame (1450 °C) melts partly into clinker balls.
const brick = new THREE.MeshStandardMaterial({ color: 0xb5651d, roughness: 0.9, emissive: 0xff5a14, emissiveIntensity: 0.25, side: THREE.DoubleSide });
