const fl = W.group({ rot: [0, 0, -4] });
const fm = new THREE.MeshStandardMaterial({ color: 0x331000, emissive: 0xffa030, emissiveIntensity: 3, transparent: true, opacity: 0.85 });
const cone = W.mesh(W.cone(14, 110, 20), fm, { at: [85, 4, 0], rot: [0, 0, 90] });
fl.add(cone);
fl.add(W.mesh(W.cyl(4, 4, 60, 12), W.metal('#c9cdd2'), { at: [165, 4, 0], rot: [0, 0, 90] }));
W.add(fl, { label: 'మంట' });
const bed = W.group({ rot: [0, 0, -4] });
const N = 90, balls = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 0), new THREE.MeshStandardMaterial({ color: 0x8a8378, roughness: 0.9, emissive: 0xff4a10, emissiveIntensity: 0.0 }), N);
bed.add(balls);
W.add(bed, { label: 'క్లింకర్' });
const u = Array.from({ length: N }, (_, i) => i / N), ph = Array.from({ length: N }, (_, i) => (i * 0.618) % 1);
const M = new THREE.Matrix4(), Q = new THREE.Quaternion(), P = new THREE.Vector3(), Z = new THREE.Vector3(), C = new THREE.Color();
W.onTick((t, dt) => {
  const k = 0.25 + 0.9 * Math.max(0.1, W.env.spool);
  for (let i = 0; i < N; i++) {
    u[i] = (u[i] + dt * 0.035 * k) % 1;
    const x = -145 + 290 * u[i], a = -1.9 + 0.9 * Math.sin(t * 1.3 * k + ph[i] * 6.28) * 0.5 + (ph[i] - 0.5) * 0.5;
